contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address target1,
        uint256 value1,
        bytes calldata data1,
        bytes32 predecessor1,
        bytes32 salt1,
        uint256 delay1,
        address target2,
        uint256 value2,
        bytes calldata data2,
        bytes32 predecessor2,
        bytes32 salt2,
        uint256 delay2
    ) public {
        uint256 minDelay = c.getMinDelay();
        require(delay1 >= minDelay);
        require(delay2 >= minDelay);

        bytes32 id1 = c.hashOperation(target1, value1, data1, predecessor1, salt1);
        bytes32 id2 = c.hashOperation(target2, value2, data2, predecessor2, salt2);
        require(id1 != id2 || (target1 == target2 && value1 == value2 && keccak256(data1) == keccak256(data2) && predecessor1 == predecessor2 && salt1 == salt2));

        c.schedule(target1, value1, data1, predecessor1, salt1, delay1);
        uint256 ts1 = c.getTimestamp(id1);
        bool ready1 = c.isOperationReady(id1);

        c.schedule(target2, value2, data2, predecessor2, salt2, delay2);
        uint256 ts2 = c.getTimestamp(id2);
        bool ready2 = c.isOperationReady(id2);

        if (id1 == id2) {
            assert(!ready2);
        } else {
            assert(ts1 > 1 && ts2 > 1 && !ready1 && !ready2);
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address target,
        uint256 value,
        bytes calldata data,
        bytes32 predecessor,
        bytes32 salt,
        uint256 delay
    ) public {
        uint256 minDelay = c.getMinDelay();
        require(delay >= minDelay);

        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        c.schedule(target, value, data, predecessor, salt, delay);

        uint256 timestamp = c.getTimestamp(id);
        bool ready = c.isOperationReady(id);

        assert(timestamp > 1 && !ready);
    }

    receive() external payable {}
}

